import { CustomerDashboardStats, DriverDashboardStats, StaffDashboardStats, StaffListResponse, UserDataResponse } from "@/types";
import { api } from "../axios";
import { store } from "@/lib/store";

export const getUser = async (): Promise<UserDataResponse> => {
  try {
    const res = await api.get("/api/users/get");

    return res.data;
  } catch (error) {
    console.error("Fetch User Error:", error);
    throw error;
  }
};

